quicksort_hoare.xu:
@main

struct Sorter {
    pub a []int
}

fn (s &mut Sorter) qsort(low int, high int) {
    if low >= high {
        <<
    }
    pivot := s.a[(low + high) / 2]
    mut i := low
    mut j := high
    while i <= j {
        while s.a[i] < pivot {
            i += 1
        }
        while s.a[j] > pivot {
            j -= 1
        }
        if i <= j {
            tmp := s.a[i]
            s.a[i] = s.a[j]
            s.a[j] = tmp
            i += 1
            j -= 1
        }
    }
    if low < j {
        s.qsort(low, j)
    }
    if i < high {
        s.qsort(i, high)
    }
}

fn main() int {
    mut checksum := 0
    mut round := 0
    while round < 5 {
        mut arr := []int{}
        mut seed := 123456789 + round * 1013904223
        mut k := 0
        while k < 100000 {
            seed = (seed * 1664525 + 1013904223) % 2147483647
            arr.push(seed)
            k += 1
        }
        mut s := Sorter{a: arr}
        s.qsort(0, s.a.len - 1)
        mut i := 0
        while i < s.a.len {
            checksum = (checksum * 31 + s.a[i]) % 1000000007
            i += 1
        }
        round += 1
    }
    println(checksum)
    << 0
}

quicksort_hoare.c:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

static void qsort_hoare(int64_t *a, int64_t low, int64_t high) {
    if (low >= high) return;
    int64_t pivot = a[(low + high) / 2];
    int64_t i = low;
    int64_t j = high;
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            int64_t tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
            i++;
            j--;
        }
    }
    if (low < j) qsort_hoare(a, low, j);
    if (i < high) qsort_hoare(a, i, high);
}

int main(void) {
    int64_t checksum = 0;
    int64_t *arr = (int64_t *)malloc(100000 * sizeof(int64_t));

    for (int round = 0; round < 5; round++) {
        int64_t seed = 123456789 + round * 1013904223LL;
        for (int k = 0; k < 100000; k++) {
            seed = (seed * 1664525 + 1013904223) % 2147483647;
            arr[k] = seed;
        }
        qsort_hoare(arr, 0, 99999);
        for (int i = 0; i < 100000; i++) {
            checksum = (checksum * 31 + arr[i]) % 1000000007;
        }
    }

    printf("%lld\n", (long long)checksum);
    free(arr);
    return 0;
}

