fn qsort(a: &mut [i64], low: isize, high: isize) {
    if low >= high {
        return;
    }
    let pivot = a[((low + high) / 2) as usize];
    let mut i = low;
    let mut j = high;
    while i <= j {
        while a[i as usize] < pivot {
            i += 1;
        }
        while a[j as usize] > pivot {
            j -= 1;
        }
