package main

import (
	"fmt"
)

func qsort(a []int64, low, high int) {
	if low >= high {
		return
	}
	pivot := a[(low+high)/2]
	i := low
	j := high
	for i <= j {
		for a[i] < pivot {
			i++
		}
		for a[j] > pivot {
			j--
		}
		if i <= j {
			a[i], a[j] = a[j], a[i]
			i++
			j--
		}
	}
	if low < j {
		qsort(a, low, j)
	}
	if i < high {
		qsort(a, i, high)
	}
}

