        unsigned lz = x ? __builtin_clzll(x) : 64;
        sum += 64 - lz;
        sum += lz;
        sum += x ? __builtin_ctzll(x) : 64;
        sum += __builtin_popcountll(x);
        x = __builtin_bswap64(x);
        sum ^= __builtin_bitreverse64(x);
