        if (!in || fread(got, 1, N, in) != N || fclose(in) != 0) return 1;
        if (memcmp(payload, got, N) != 0) return 1;
        sum += got[0] + got[N / 2] + got[N - 1];
    }
    printf("%lld\n", (long long)sum);
    free(got);
    free(payload);
    return 0;
}

