#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    char *data;
    int64_t len;
    int64_t cap;
} StringBuilder;

static void sb_init(StringBuilder *sb) {
    sb->cap = 64;
    sb->len = 0;
    sb->data = (char *)malloc(sb->cap);
}

static void sb_write_byte(StringBuilder *sb, char b) {
    if (sb->len + 1 >= sb->cap) {
        sb->cap *= 2;
        sb->data = (char *)realloc(sb->data, sb->cap);
    }
    sb->data[sb->len++] = b;
}

