package main

import (
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"strconv"
	"strings"
)

// HTTP high-concurrency throughput over a loopback server.
//
// 16 concurrent workers x 200 requests. Every request opens a fresh TCP
// connection and sends "Connection: close", so all languages pay the same
// connect/teardown cost and no keep-alive reuse can hide server differences.
//
// The server side uses each language's idiomatic HTTP server (Go: net/http,
// Rust: std::net, Xu: net/http). The client side is raw TCP on every
// language so the wire traffic is identical.
//
// stdout: completed request count, then the order-independent checksum
// (sum of the per-worker FNV-1a-32 hashes over the response bodies).

const conns = 16
const reqPerConn = 200

func expectedBody(seq int) string {
	return "pong-" + strconv.Itoa(seq) + "\n"
}

func fnvUpdate(h uint32, body string) uint32 {
	for i := 0; i < len(body); i++ {
		h ^= uint32(body[i])
		h *= 16777619
	}
	return h
}

func handler(w http.ResponseWriter, r *http.Request) {
	seq := strings.TrimPrefix(r.URL.Path, "/r/")
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "pong-%s\n", seq)
}

func worker(addr string, base int, out chan<- uint32) {
	h := uint32(2166136261)
	for i := 0; i < reqPerConn; i++ {
		seq := base + i
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			fmt.Fprintln(os.Stderr, "dial:", err)
			os.Exit(1)
		}
		req := "GET /r/" + strconv.Itoa(seq) + " HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n"
		if _, err := conn.Write([]byte(req)); err != nil {
			fmt.Fprintln(os.Stderr, "write:", err)
			os.Exit(1)
		}
		resp, err := io.ReadAll(conn)
		conn.Close()
		if err != nil {
			fmt.Fprintln(os.Stderr, "read:", err)
			os.Exit(1)
		}
		raw := string(resp)
		idx := strings.Index(raw, "\r\n\r\n")
		if idx < 0 {
			fmt.Fprintln(os.Stderr, "no header end")
			os.Exit(1)
		}
		body := raw[idx+4:]
		if body != expectedBody(seq) {
			fmt.Fprintln(os.Stderr, "body mismatch")
			os.Exit(1)
		}
		h = fnvUpdate(h, body)
	}
	out <- h
}

func main() {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		fmt.Fprintln(os.Stderr, "listen:", err)
		os.Exit(1)
	}
	port := ln.Addr().(*net.TCPAddr).Port
	addr := "127.0.0.1:" + strconv.Itoa(port)
	srv := &http.Server{Handler: http.HandlerFunc(handler)}
	go srv.Serve(ln)

	out := make(chan uint32, conns)
	for w := 0; w < conns; w++ {
		go worker(addr, w*reqPerConn, out)
	}
	var sum uint64
	for i := 0; i < conns; i++ {
		sum += uint64(<-out)
	}
	fmt.Println(conns * reqPerConn)
	fmt.Println(sum)
}

http_concurrent.rust:
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::mpsc;
use std::thread;

// HTTP high-concurrency throughput over a loopback server.
//
// 16 concurrent workers x 200 requests. Every request opens a fresh TCP
// connection and sends "Connection: close", so all languages pay the same
// connect/teardown cost and no keep-alive reuse can hide server differences.
//
// The server side uses each language's idiomatic HTTP server (Go: net/http,
// Rust: std::net, Xu: net/http). The client side is raw TCP on every
// language so the wire traffic is identical.
//
// stdout: completed request count, then the order-independent checksum
// (sum of the per-worker FNV-1a-32 hashes over the response bodies).

const CONNS: usize = 16;
const REQ_PER_CONN: usize = 200;

fn expected_body(seq: usize) -> String {
    format!("pong-{}\n", seq)
}

fn fnv_update(mut h: u32, body: &[u8]) -> u32 {
    for &b in body {
        h ^= b as u32;
        h = h.wrapping_mul(16777619);
    }
    h
}

fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > haystack.len() {
        return None;
    }
    for i in 0..=(haystack.len() - needle.len()) {
        if &haystack[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

fn handle(mut conn: TcpStream) {
    let mut buf = [0u8; 1024];
    let mut acc: Vec<u8> = Vec::new();
    let mut header_end: Option<usize> = None;
    while header_end.is_none() {
        let n = match conn.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(_) => return,
        };
        acc.extend_from_slice(&buf[..n]);
        header_end = find(&acc, b"\r\n\r\n");
    }
    let header_end = match header_end {
        Some(p) => p,
        None => return,
    };
    let head = String::from_utf8_lossy(&acc[..header_end]).to_string();
    let mut parts = head.split_whitespace();
    let _method = parts.next();
    let path = parts.next().unwrap_or("");
    let seq: usize = path
        .strip_prefix("/r/")
        .unwrap_or("")
        .parse::<usize>()
        .unwrap_or(0);
    let body = expected_body(seq);
    let resp = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body.len(),
        body
    );
    let _ = conn.write_all(resp.as_bytes());
    let _ = conn.flush();
}

fn worker(addr: &str, base: usize, out: mpsc::Sender<u32>) {
    let mut h: u32 = 2166136261;
    for i in 0..REQ_PER_CONN {
        let seq = base + i;
        let mut conn = match TcpStream::connect(addr) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("dial: {}", e);
                std::process::exit(1);
            }
        };
        let req = format!(
            "GET /r/{} HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n",
            seq
        );
        if conn.write_all(req.as_bytes()).is_err() {
            eprintln!("write failed");
            std::process::exit(1);
        }
        let mut resp = Vec::new();
        if conn.read_to_end(&mut resp).is_err() {
            eprintln!("read failed");
            std::process::exit(1);
        }
        drop(conn);
        let idx = match find(&resp, b"\r\n\r\n") {
            Some(p) => p,
            None => {
                eprintln!("no header end");
                std::process::exit(1);
            }
        };
        let body = &resp[idx + 4..];
        let want = expected_body(seq);
        if body != want.as_bytes() {
            eprintln!("body mismatch");
            std::process::exit(1);
        }
        h = fnv_update(h, body);
    }
    let _ = out.send(h);
}

fn main() {
    let ln = TcpListener::bind("127.0.0.1:0").expect("listen failed");
    let port = ln.local_addr().expect("local_addr failed").port();
    let addr = format!("127.0.0.1:{}", port);

    thread::spawn(move || {
        for stream in ln.incoming() {
            match stream {
                Ok(s) => {
                    thread::spawn(move || {
                        handle(s);
                    });
                }
                Err(_) => break,
            }
        }
    });

    let (tx, rx) = mpsc::channel::<u32>();
    for w in 0..CONNS {
        let a = addr.clone();
        let t = tx.clone();
        thread::spawn(move || {
            worker(&a, w * REQ_PER_CONN, t);
        });
    }
    drop(tx);

    let mut sum: u64 = 0;
    for _ in 0..CONNS {
        sum += rx.recv().expect("worker dropped") as u64;
    }
    println!("{}", CONNS * REQ_PER_CONN);
    println!("{}", sum);
}
